<?php
declare(strict_types=1);use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Branches\BranchClock;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);$branch=(int)($_GET['branch_id']??$u['default_branch_id']);ApiGuard::branch($db,$u,$branch);$clock=new BranchClock($db);$date=$_GET['date']??$clock->now((int)$u['business_id'],$branch)->format('Y-m-d');[$from,$to]=$clock->utcRangeForLocalDate((int)$u['business_id'],$branch,$date);$q=$db->prepare("SELECT COUNT(*) sales_count,COALESCE(SUM(total),0) sales_total,COALESCE(SUM(cost_total),0) cost_total,COALESCE(SUM(tax),0) tax_total FROM sales WHERE business_id=? AND branch_id=? AND status='completed' AND completed_at_utc>=? AND completed_at_utc<?");$q->execute([(int)$u['business_id'],$branch,$from,$to]);$r=$q->fetch();echo json_encode(['ok'=>true,'branch_id'=>$branch,'local_date'=>$date,'timezone'=>$clock->timezone((int)$u['business_id'],$branch)->getName(),'utc_range'=>[$from,$to],'summary'=>$r],JSON_UNESCAPED_UNICODE);}catch(Throwable$e){http_response_code(in_array((int)$e->getCode(),[401,403],true)?(int)$e->getCode():422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}